/**
 * Current usage and limit checks for one organization.
 *
 * Owner D. Returns the raw counters *and* the plan ceilings side by side, so a
 * dashboard can render a meter without knowing the plan table itself.
 *
 * Must call (do not reimplement): can, assertOrgScope, getPlanLimits
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getPlanLimits } from "@/config/plan-limits";
import { requireActorFor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { orgIdSchema } from "@/schemas/common";
import { checkLimit } from "@/server/services/billing-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { getUsage } from "@/server/services/usage-service";
import type { LimitedResource } from "@/types/billing";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ orgId: string }> };

const REPORTED: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function GET(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  void request;

  try {
    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { orgId } = await context.params;
    const parsed = orgIdSchema.safeParse(orgId);
    if (!parsed.success) {
      return failure("validation_failed", "Malformed organization id.");
    }

    const actor = await requireActorFor(parsed.data);
    assertOrgScope(actor, parsed.data);

    if (!can(actor, "org:read", { kind: "organization", orgId: parsed.data })) {
      return failure("forbidden", "You cannot read this organization.");
    }

    const [{ organization }, usage] = await Promise.all([
      getOrganizationSummary(actor, parsed.data),
      getUsage(actor, parsed.data),
    ]);

    const limits = getPlanLimits(organization.plan);
    const checks = await Promise.all(
      REPORTED.map((resource) => checkLimit(parsed.data, resource, 0)),
    );

    return Response.json({ plan: organization.plan, limits, usage, checks });
  } catch (error) {
    return errorResponse(error);
  }
}

import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}

