2	import { describe, expect, it } from "vitest";
3	import {
4	  PLAN_LIMITS,
5	  PLAN_ORDER,
6	  UNLIMITED,
7	  getLimit,
8	  getPlanLimits,
9	  planAtLeast,
10	  wouldExceedLimit,
11	} from "@/config/plan-limits";
12	import { PLAN_IDS, type LimitedResource } from "@/types/billing";
13	
14	const RESOURCES: readonly LimitedResource[] = [
15	  "seats",
16	  "projects",
17	  "issuesPerProject",
18	  "storageMb",
19	  "apiRequestsPerHour",
20	  "webhooks",
21	];
22	
23	describe("config/plan-limits", () => {
24	  it("declares limits for every plan id", () => {
25	    for (const plan of PLAN_IDS) {
26	      expect(getPlanLimits(plan).plan).toBe(plan);
27	    }
28	    expect([...PLAN_ORDER].sort()).toEqual([...PLAN_IDS].sort());
29	  });
30	
31	  it("never shrinks a quota as the plan gets richer", () => {
32	    for (const resource of RESOURCES) {
33	      for (let i = 1; i < PLAN_ORDER.length; i += 1) {
34	        const previous = PLAN_ORDER[i - 1];
35	        const current = PLAN_ORDER[i];
36	        if (!previous || !current) continue;
37	        expect(
38	          getLimit(current, resource),
39	          `${resource}: ${current} vs ${previous}`,
40	        ).toBeGreaterThanOrEqual(getLimit(previous, resource));
41	      }
42	    }
43	  });
44	
45	  it("orders plans cheapest to richest", () => {
46	    expect(planAtLeast("growth", "starter")).toBe(true);
47	    expect(planAtLeast("starter", "growth")).toBe(false);
48	    expect(planAtLeast("free", "free")).toBe(true);
49	    expect(planAtLeast("enterprise", "free")).toBe(true);
50	  });
51	
52	  it("uses Infinity as the unlimited sentinel on enterprise", () => {
53	    expect(PLAN_LIMITS.enterprise.seats).toBe(UNLIMITED);
54	    expect(Number.isFinite(PLAN_LIMITS.enterprise.projects)).toBe(false);
55	    expect(Number.isFinite(PLAN_LIMITS.free.projects)).toBe(true);
56	  });
57	
58	  it("never exceeds an unlimited quota", () => {
59	    expect(wouldExceedLimit("enterprise", "seats", 1_000_000)).toBe(false);
60	    expect(wouldExceedLimit("enterprise", "projects", 10_000, 10_000)).toBe(false);
61	  });
62	
63	  it("refuses the request that would cross the boundary, not the one that reaches it", () => {
64	    // free allows 3 seats
65	    expect(wouldExceedLimit("free", "seats", 2)).toBe(false);
66	    expect(wouldExceedLimit("free", "seats", 3)).toBe(true);
67	    expect(wouldExceedLimit("free", "seats", 0, 3)).toBe(false);
68	    expect(wouldExceedLimit("free", "seats", 0, 4)).toBe(true);
69	  });
70	
71	  it("blocks webhooks entirely on the free plan", () => {
72	    expect(getLimit("free", "webhooks")).toBe(0);
73	    expect(wouldExceedLimit("free", "webhooks", 0)).toBe(true);
74	    expect(wouldExceedLimit("starter", "webhooks", 0)).toBe(false);
75	  });
